#[test]#[allow(clippy::field_reassign_with_default)]fn original_tree_roundtrip_and_all_ranges() {use crate::smart_eat::SmartEat;let m=SmartEat::default();let common=CommonSettings {enabled:true,hidden:false,key_bind:Value::Null};let tree=smart::serialize_smart_eat(&m,&common,JsonFormat::Interop,&str::to_owned).unwrap();let names=tree["value"].as_array().unwrap().iter().map(|v|v["name"].as_str().unwrap()).collect::<Vec<_>>();assert_eq!(names,["Bind","Hidden","SwapBackDelay","PreferGappleHealthThreshold","PreferNotchAppleHealthThreshold","PreferHealthPotHealthThreshold","CombatPauseTime","NotDuringCombat","SilentOffhand","AutoEat"]);assert_eq!(tree["value"][2]["range"],json!({"from":1,"to":20}));assert_eq!(tree["value"][6]["suffix"],"ticks");assert_eq!(tree["value"][8]["value"][1]["value"][1]["range"],json!({"from":30,"to":70}));assert_eq!(tree["value"][9]["value"][1]["key"],"liquidbounce.module.smartEat.autoEat.minHunger");let file=smart::serialize_smart_eat(&m,&common,JsonFormat::File,&str::to_owned).unwrap();assert_eq!(file["value"][0],json!({"name":"Enabled","value":true}));let mut p=SettingsPatch::default();smart::parse_smart_eat(&mut p,&nodes(&file,"SmartEat","SmartEat").unwrap());assert!(p.issues.is_empty());assert_eq!(p.changes.len(),11);let mut restored=SmartEat::default();restored.min_hunger = -1;for SettingChange::SmartEat(s) in p.changes {s.apply(&mut restored);}assert_eq!(m,restored);}
#[test]fn raw_value_conversion_first_duplicate_and_independent_leaf_errors() {use smart::SmartEatSetting as S;let file=json!({"name":"SmartEat","value":[{"name":"SwapBackDelay","value":-100},{"name":"SwapBackDelay","value":5},{"name":"PreferGappleHealthThreshold","value":"NaN"},{"name":"CombatPauseTime","value":4294967297_i64},{"name":"NotDuringCombat","value":"TRUE"},{"name":"SilentOffhand","value":[{"name":"Enabled","value":false},{"name":"RenderSlot","value":[{"name":"Enabled","value":true},{"name":"Offset","value":"bad"}]}]},{"name":"AutoEat","value":[{"name":"Enabled","value":false},{"name":"MinHunger","value":-1}]}]});let mut p=SettingsPatch::default();smart::parse_smart_eat(&mut p,&nodes(&file,"SmartEat","SmartEat").unwrap());assert_eq!(p.issues.len(),1);assert_eq!(p.issues[0].path,"SmartEat.SilentOffhand.RenderSlot.Offset");assert!(!p.issues[0].message.is_empty());assert!(matches!(p.changes[0],SettingChange::SmartEat(S::SwapBackDelay(-100))));assert!(matches!(p.changes[1],SettingChange::SmartEat(S::PreferGappleHealthThreshold(v))if v.is_nan()));assert!(matches!(p.changes[2],SettingChange::SmartEat(S::CombatPauseTime(1))));assert!(matches!(p.changes[3],SettingChange::SmartEat(S::NotDuringCombat(true))));assert!(matches!(p.changes[4],SettingChange::SmartEat(S::SilentOffhand(false))));assert!(matches!(p.changes.last(),Some(SettingChange::SmartEat(S::MinHunger(-1)))));}
#[test]#[allow(clippy::field_reassign_with_default)]fn malformed_child_does_not_block_other_child_and_nonfinite_serialize_fails() {let file=json!({"name":"SmartEat","value":[{"name":"SilentOffhand","value":true},{"name":"AutoEat","value":[{"name":"MinHunger","value":7}]}]});let mut p=SettingsPatch::default();smart::parse_smart_eat(&mut p,&nodes(&file,"SmartEat","SmartEat").unwrap());assert_eq!(p.issues.len(),1);assert_eq!(p.changes,[SettingChange::SmartEat(smart::SmartEatSetting::MinHunger(7))]);let mut m=crate::smart_eat::SmartEat::default();m.prefer_health_pot_health=f32::INFINITY;assert!(smart::serialize_smart_eat(&m,&CommonSettings {enabled:false,hidden:false,key_bind:Value::Null},JsonFormat::File,&str::to_owned).is_err());}
